#!/bin/zsh
# Builds Gloaming and wraps it in a minimal, ad-hoc-signed .app bundle (build/Gloaming.app).
# Works with the Command Line Tools alone; no Xcode or signing identity required.
set -euo pipefail

cd "${0:A:h}/.."
CONFIG="${1:-release}"

swift build -c "$CONFIG"
BIN="$(swift build -c "$CONFIG" --show-bin-path)/Gloaming"

APP="build/Gloaming.app"
rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"
cp "$BIN" "$APP/Contents/MacOS/Gloaming"

# App icon (generated by `Gloaming --icon … --icon-variant …`, committed to the repo).
ICON="Gloaming/Resources/AppIcon.icns"
if [[ -f "$ICON" ]]; then cp "$ICON" "$APP/Contents/Resources/AppIcon.icns"; fi

cat > "$APP/Contents/Info.plist" <<'PLIST'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
    <key>CFBundleExecutable</key>         <string>Gloaming</string>
    <key>CFBundleIconFile</key>           <string>AppIcon</string>
    <key>CFBundleIdentifier</key>         <string>io.github.gloaming.Gloaming</string>
    <key>CFBundleName</key>               <string>Gloaming</string>
    <key>CFBundlePackageType</key>        <string>APPL</string>
    <key>CFBundleShortVersionString</key> <string>0.4.0</string>
    <key>CFBundleVersion</key>            <string>1</string>
    <key>LSMinimumSystemVersion</key>     <string>14.0</string>
    <key>NSHighResolutionCapable</key>    <true/>
</dict>
</plist>
PLIST

# Ad-hoc signature ("-") so Gatekeeper/TCC see a consistent identity locally.
codesign --force --sign - "$APP"
echo "Built $PWD/$APP"
